create table if not exists audit_log (id bigint not null auto_increment comment 'audit primary key', log_no varchar(32) not null comment 'log number', operator_employee_id varchar(128) comment 'operator name', action varchar(128) not null comment 'action', resource_type varchar(32) comment 'resource type', resource_id bigint comment 'resource id', request_id varchar(128) comment 'request id', created_at datetime(3) not null default current_timestamp(3) comment 'created time', primary key(id), unique key uk_audit_log_no(log_no)) engine=InnoDB default charset=utf8mb4 comment='audit log';

